UPDATE payroll_country_configs pcc SET effective_from=DATE '2024-01-01', version='GH-2024.01', updated_at=NOW() FROM countries c WHERE pcc.country_id=c.id AND c.iso_code='GH' AND pcc.version='GH-2026.01';
UPDATE statutory_rule_versions srv SET version='GH-2024.01', effective_from=DATE '2024-01-01', updated_at=NOW() FROM statutory_rules sr JOIN countries c ON c.id=sr.country_id WHERE srv.statutory_rule_id=sr.id AND c.iso_code='GH' AND sr.code='GH-PAYE' AND srv.company_id IS NULL AND srv.version='GH-2026.01';
UPDATE statutory_rule_versions srv SET maximum_amount=5750, effective_from=DATE '2026-01-01', updated_at=NOW() FROM statutory_rules sr JOIN countries c ON c.id=sr.country_id WHERE srv.statutory_rule_id=sr.id AND c.iso_code='GH' AND sr.code='GH-SSNIT' AND srv.company_id IS NULL AND srv.version='GH-2026.01';
